import androidx.compose.ui.text.input.KeyboardType
import androidx.compose.ui.unit.dp
import com.example.code.controller.LotteryController
import com.example.code.controller.LotteryUpdateController
import com.example.code.model.Campsite
import com.example.code.model.Lottery
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch
import java.util.TimeZone

/**
 * [lottery] is the snapshot captured when editing began; [currentLottery] is live.
 * [onSave] returns only after persistence succeeds. Failed saves keep form values.
 */
@Composable
fun EditLotteryScreen(
    lottery: Lottery,
    currentLottery: Lottery = lottery,
    ownerId: String,
    campsites: List<Campsite>,
    onSave: suspend (List<Campsite>, Lottery) -> Unit,
    onSaved: () -> Unit,
    onCancel: () -> Unit,
    clock: () -> Long = System::currentTimeMillis,
) {
    val candidates = campsites.filter { it.ownerId == ownerId && it.id.isNotBlank() }
        .distinctBy { it.id }
        .sortedWith(compareBy<Campsite> { it.name.lowercase() }.thenBy { it.id })
    // Other owners' campsites aren't listed here, since only they can change them
    var selectedIds by rememberSaveable(lottery.id, ownerId) {
        mutableStateOf(
            ArrayList(
                LotteryController.includedCampsites(lottery).map { it.id }
                    .filter { id -> candidates.any { it.id == id } },
            ),
        )
    }
    var registrationStart by rememberSaveable(lottery.id) { mutableLongStateOf(lottery.registrationStart) }
    var registrationEnd by rememberSaveable(lottery.id) { mutableLongStateOf(lottery.registrationEnd) }
    var bookingStart by rememberSaveable(lottery.id) { mutableLongStateOf(lottery.bookingStart) }
    var bookingEnd by rememberSaveable(lottery.id) { mutableLongStateOf(lottery.bookingEnd) }
    var winners by rememberSaveable(lottery.id) { mutableStateOf(lottery.winnerCount.toString()) }
    var capacity by rememberSaveable(lottery.id) {
        mutableStateOf(lottery.waitlistCapacity?.toString().orEmpty())
    }
    var busy by remember(lottery.id) { mutableStateOf(false) }
    var error by rememberSaveable(lottery.id) { mutableStateOf<String?>(null) }
    var now by remember(lottery.id) { mutableLongStateOf(clock()) }
    val scope = rememberCoroutineScope()
    LaunchedEffect(lottery.id, clock) {
        while (true) {
            delay(1_000L)
            now = clock()
        }
    }
    val editable = currentLottery.ownerId == ownerId &&
            LotteryUpdateController.canEdit(currentLottery, now)
    val enabled = editable && !busy
    val sitesAndStayEnabled = enabled && currentLottery.waitingListCount == 0
    val startEnabled = enabled && now < currentLottery.registrationStart
    BackHandler { if (!busy) onCancel() }

    Column(
        modifier = Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(12.dp),
    ) {
        Text("Edit lottery", style = MaterialTheme.typography.headlineSmall)
        Text("All dates and times use ${TimeZone.getDefault().id}.")
        Text("Current waiting list: ${currentLottery.waitingListCount} entrants")
        if (!editable) {
            Text("This lottery cannot be edited after registration closes or winners are drawn.")
        }
        if (currentLottery.waitingListCount > 0) {
            Text("Included campsites and stay dates stay fixed while entrants are on the waiting list.")
        }
        if (now >= currentLottery.registrationStart) {
            Text("Registration has opened, so its start time stays fixed.")
        }
        Text("Select campsites", style = MaterialTheme.typography.titleMedium)
        Text("Selected: ${selectedIds.size}")
        candidates.forEach { campsite ->
            val checked = campsite.id in selectedIds
            Row(
                modifier = Modifier.fillMaxWidth()
                    .testTag("edit-lottery-campsite-${campsite.id}")
                    .toggleable(
                        value = checked,
                        enabled = sitesAndStayEnabled,
                        role = Role.Checkbox,
                        onValueChange = { selected ->
                            selectedIds = if (selected) ArrayList((selectedIds + campsite.id).distinct())
                            else ArrayList(selectedIds.filterNot { it == campsite.id })
                        },
                    ).padding(vertical = 4.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Checkbox(checked = checked, onCheckedChange = null, enabled = sitesAndStayEnabled)
                Column {
                    Text(campsite.name)
                    if (campsite.location.isNotBlank()) Text(campsite.location)
                }
            }
        }
        TextButton(
            onClick = { selectedIds = arrayListOf() },
            enabled = sitesAndStayEnabled,
        ) { Text("Clear campsite selection") }

        Text("Registration period", style = MaterialTheme.typography.titleMedium)
        LotteryDateTimeField("Registration starts", registrationStart, startEnabled) { registrationStart = it }
        LotteryDateTimeField("Registration ends", registrationEnd, enabled) { registrationEnd = it }
        Text("Booking period", style = MaterialTheme.typography.titleMedium)
        LotteryDateTimeField("Booking starts", bookingStart, sitesAndStayEnabled) { bookingStart = it }
        LotteryDateTimeField("Booking ends", bookingEnd, sitesAndStayEnabled) { bookingEnd = it }
        OutlinedTextField(
            value = winners,
            onValueChange = { winners = it },
            label = { Text("Number of winners") },
            enabled = enabled,
            singleLine = true,
            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
            modifier = Modifier.fillMaxWidth().testTag("editLotteryWinners"),
        )
        OutlinedTextField(
            value = capacity,
            onValueChange = { capacity = it },
            label = { Text("Waiting-list capacity (optional)") },
            supportingText = { Text("Leave blank for unlimited. Existing entrants must still fit.") },
            enabled = enabled,
            singleLine = true,
            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
            modifier = Modifier.fillMaxWidth().testTag("editLotteryCapacity"),
        )
        error?.let { Text(it, color = MaterialTheme.colorScheme.error) }
        if (busy) {
            CircularProgressIndicator()
            Text("Saving lottery changes…")
        }
        Button(
            enabled = enabled,
            modifier = Modifier.fillMaxWidth().testTag("saveLotteryChanges"),
            onClick = {
                val draft = try {
                    require(selectedIds.isNotEmpty()) { "Select at least one campsite." }
                    val selected = selectedIds.map { id ->
                        requireNotNull(candidates.firstOrNull { it.id == id }) {
                            "A selected campsite is no longer available. Clear the selection and choose again."
                        }
                    }
                    val count = requireNotNull(winners.trim().toIntOrNull()) {
                        "Enter a whole number of winners."
                    }
                    val cap = if (capacity.isBlank()) null else requireNotNull(capacity.trim().toIntOrNull()) {
                        "Enter a whole-number capacity or leave it blank."
                    }
                    val settings = lottery.copy(
                        registrationStart = registrationStart,
                        registrationEnd = registrationEnd,
                        bookingStart = bookingStart,
                        bookingEnd = bookingEnd,
                        winnerCount = count,
                        waitlistCapacity = cap,
                    )
                    selected to LotteryUpdateController.revalidate(
                        lottery, currentLottery, ownerId, selected, settings, clock(),
                    )
                } catch (invalid: IllegalArgumentException) {
                    error = invalid.message
                    null
                }
                if (draft != null && !busy) {
                    busy = true
                    error = null
                    scope.launch {
                        try {
                            onSave(draft.first, draft.second)
                            onSaved()
                        } catch (cancelled: CancellationException) {
                            throw cancelled
                        } catch (failure: Exception) {
                            error = "Could not update lottery: ${failure.message ?: "Please try again."}"
                        } finally {
                            busy = false
                        }
                    }
                }
            },
        ) { Text("Save changes") }
        TextButton(
            onClick = onCancel,
            enabled = !busy,
            modifier = Modifier.testTag("cancelLotteryChanges"),
        ) { Text("Cancel") }
    }
}
